def is_fresh(created_at, now, ttl):
    """Whether a cached value can be reused at this instant."""
    if ttl < 0 or now < created_at:
        raise ValueError("invalid cache clock or TTL")
    return now - created_at <= ttl

from cache_policy import is_fresh

def test_before_expiry():
    assert is_fresh(100, 109, 10) is True

def test_after_expiry():
    assert is_fresh(100, 111, 10) is False

def test_exact_expiry():
    assert is_fresh(100, 110, 10) is False

def test_invalid_clock():
    try:
        is_fresh(100, 99, 10)
    except ValueError:
        return
    assert False, "backward clock must be rejected"

def stock_totals(entries):
    """Aggregate signed stock movements, retaining first-seen SKU order."""
    totals = {}
    for sku, quantity in entries:
        totals[sku] = quantity
    return list(totals.items())

from stock_summary import stock_totals

def test_empty():
    assert stock_totals([]) == []

def test_single_movement():
    assert stock_totals([("bolt", 4)]) == [("bolt", 4)]

def test_distinct_skus_keep_order():
    assert stock_totals([("nut", 2), ("bolt", 3)]) == [("nut", 2), ("bolt", 3)]

def test_repeated_sku_accumulates():
    assert stock_totals([("bolt", 5), ("nut", 2), ("bolt", -1)]) == [("bolt", 4), ("nut", 2)]
